{"command": "cat > /prediction.json << 'JSONEOF'
{
    "vllm/attention/ops/triton_prefill_attention.py": {
        "_fwd_kernel": "@triton.jit\ndef _fwd_kernel(\n    Q,\n    K,\n    V,\n    sm_scale,\n    B_Start_Loc,\n    B_Seqlen,\n    Out,\n    stride_qbs,\n    stride_qh,\n    stride_kbs,\n    stride_kh,\n    stride_vbs,\n    stride_vh,\n    stride_obs,\n    stride_oh,\n    kv_group_num: tl.constexpr,\n    BLOCK_M: tl.constexpr,\n    BLOCK_DMODEL: tl.constexpr,\n    BLOCK_N: tl.constexpr,\n    IS_CAUSAL: tl.constexpr,\n    SLIDING_WINDOW_Q: tl.constexpr,\n    SLIDING_WINDOW_K: tl.constexpr,\n    Lk: tl.constexpr,\n):\n    cur_batch = tl.program_id(0)\n    cur_head = tl.program_id(1)\n    start_m = tl.program_id(2)\n\n    cur_kv_head = cur_head // kv_group_num\n\n    cur_batch_seq_len = tl.load(B_Seqlen + cur_batch)\n    cur_batch_in_all_start_index = tl.load(B_Start_Loc + cur_batch)\n\n    block_start_loc = BLOCK_M * start_m\n\n    # initialize offsets\n    offs_n = tl.arange(0, BLOCK_N)\n    offs_d = tl.arange(0, BLOCK_DMODEL)\n    offs_m = start_m * BLOCK_M + tl.arange(0, BLOCK_M)\n    off_q = (\n        (cur_batch_in_all_start_index + offs_m[:, None]) * stride_qbs\n        + cur_head * stride_qh\n        + offs_d[None, :]\n    )\n\n    mask_d = offs_d < Lk\n\n    q = tl.load(\n        Q + off_q,\n        mask=(offs_m[:, None] < cur_batch_seq_len) & (mask_d[None, :]),\n        other=0.0,\n    )\n\n    k_ptrs = K + offs_n[None, :] * stride_kbs + cur_kv_head * stride_kh + offs_d[:, None]\n    v_ptrs = V + offs_n[:, None] * stride_vbs + cur_kv_head * stride_vh + offs_d[None, :]\n\n    # initialize pointer to m and l\n    m_i = tl.zeros([BLOCK_M], dtype=tl.float32) - float(\"inf\")\n    l_i = tl.zeros([BLOCK_M], dtype=tl.float32)\n    acc = tl.zeros([BLOCK_M, BLOCK_DMODEL], dtype=tl.float32)\n\n    block_mask = tl.where(block_start_loc < cur_batch_seq_len, 1, 0)\n\n    end_n = (\n        cur_batch_seq_len\n        if not IS_CAUSAL\n        else tl.minimum((start_m + 1) * BLOCK_M, cur_batch_seq_len)\n    )\n    for start_n in range(0, block_mask * end_n, BLOCK_N):\n        start_n = tl.multiple_of(start_n, BLOCK_N)\n        # -- compute qk ----\n        k = tl.load(\n            k_ptrs + (cur_batch_in_all_start_index + start_n) * stride_kbs,\n            mask=((start_n + offs_n[None, :]) < cur_batch_seq_len) & (mask_d[:, None]),\n            other=0.0,\n        )\n\n        qk = tl.zeros([BLOCK_M, BLOCK_N], dtype=tl.float32)\n        qk += tl.dot(q, k)\n        qk *= sm_scale\n\n        # Apply causal and sliding window masks\n        if IS_CAUSAL:\n            causal_mask = offs_m[:, None] >= (start_n + offs_n[None, :])\n            if SLIDING_WINDOW_Q > 0:\n                sw_q_mask = (start_n + offs_n[None, :]) >= offs_m[:, None] - SLIDING_WINDOW_Q\n                mask = causal_mask & sw_q_mask\n            else:\n                mask = causal_mask\n        else:\n            if SLIDING_WINDOW_Q > 0:\n                mask = (start_n + offs_n[None, :]) >= offs_m[:, None] - SLIDING_WINDOW_Q\n            else:\n                mask = tl.full([BLOCK_M, BLOCK_N], True, dtype=tl.int1)\n            \n            if SLIDING_WINDOW_K > 0:\n                sw_k_mask = (start_n + offs_n[None, :]) <= offs_m[:, None] + SLIDING_WINDOW_K\n                mask = mask & sw_k_mask\n\n        qk = tl.where(mask, qk, float(\"-inf\"))\n\n        # -- compute m_ij, p, l_ij\n        m_ij = tl.max(qk, 1)\n        p = tl.exp(qk - m_ij[:, None])\n        l_ij = tl.sum(p, 1)\n        # -- update m_i and l_i\n        m_i_new = tl.maximum(m_i, m_ij)\n        alpha = tl.exp(m_i - m_i_new)\n        beta = tl.exp(m_ij - m_i_new)\n        l_i_new = alpha * l_i + beta * l_ij\n        # -- update output accumulator --\n        # scale p\n        p_scale = beta / l_i_new\n        p = p * p_scale[:, None]\n        # scale acc\n        acc_scale = l_i / l_i_new * alpha\n        acc = acc * acc_scale[:, None]\n        # update acc\n        v = tl.load(\n            v_ptrs + (cur_batch_in_all_start_index + start_n) * stride_vbs,\n            mask=((start_n + offs_n[:, None]) < cur_batch_seq_len) & (mask_d[None, :]),\n            other=0.0,\n        )\n\n        p = p.to(v.dtype)\n        acc += tl.dot(p, v)\n        # update m_i and l_i\n        l_i = l_i_new\n        m_i = m_i_new\n    # initialize pointers to output\n    off_o = (\n        (cur_batch_in_all_start_index + offs_m[:, None]) * stride_obs\n        + cur_head * stride_oh\n        + offs_d[None, :]\n    )\n    out_ptrs = Out + off_o\n    tl.store(\n        out_ptrs, acc, mask=(offs_m[:, None] < cur_batch_seq_len) & (mask_d[None, :])\n    )"
    }
}
JSONEOF"}

